-- CPF postgresql initial baseline for mbrDB


-- CPF_LOGICAL_DATABASE=mbrDB
-- CPF_USE_LOGICAL_DATABASE=mbrDB
CREATE TABLE mbr_member (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    member_no VARCHAR(50) NOT NULL,
    customer_no VARCHAR(50) NOT NULL,
    login_id VARCHAR(80) NOT NULL,
    password_hash VARCHAR(300),
    login_fail_count INTEGER NOT NULL DEFAULT 0,
    password_change_required_yn CHAR(1) NOT NULL DEFAULT 'N',
    password_expire_at TIMESTAMP,
    name VARCHAR(100) NOT NULL,
    email VARCHAR(200),
    mobile_no VARCHAR(50),
    member_status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE',
    lock_yn CHAR(1) NOT NULL DEFAULT 'N',
    withdraw_yn CHAR(1) NOT NULL DEFAULT 'N',
    channel_code VARCHAR(30) NOT NULL DEFAULT 'WEB',
    joined_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_login_at TIMESTAMP,
    description TEXT,
    version_no BIGINT NOT NULL DEFAULT 0,
    created_by VARCHAR(100) NOT NULL DEFAULT 'SYSTEM',
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by VARCHAR(100) NOT NULL DEFAULT 'SYSTEM',
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    CONSTRAINT uk_mbr_member_no UNIQUE (member_no),
    CONSTRAINT uk_mbr_member_login_id UNIQUE (login_id),
    CONSTRAINT ck_mbr_member_version CHECK (version_no >= 0)
);
CREATE INDEX ix_mbr_member_customer ON mbr_member (customer_no);
CREATE INDEX ix_mbr_member_status ON mbr_member (member_status, lock_yn, withdraw_yn);
COMMENT ON TABLE mbr_member IS 'MBR 회원';
COMMENT ON COLUMN mbr_member.id IS '회원 순번';
COMMENT ON COLUMN mbr_member.member_no IS '회원 번호';
COMMENT ON COLUMN mbr_member.customer_no IS '고객 번호';
COMMENT ON COLUMN mbr_member.login_id IS '로그인 ID';
COMMENT ON COLUMN mbr_member.password_hash IS '회원 비밀번호 hash';
COMMENT ON COLUMN mbr_member.login_fail_count IS '로그인 실패 횟수';
COMMENT ON COLUMN mbr_member.password_change_required_yn IS '비밀번호 강제 변경 여부';
COMMENT ON COLUMN mbr_member.password_expire_at IS '비밀번호 만료 일시';
COMMENT ON COLUMN mbr_member.name IS '회원명';
COMMENT ON COLUMN mbr_member.email IS '이메일';
COMMENT ON COLUMN mbr_member.mobile_no IS '휴대폰 번호';
COMMENT ON COLUMN mbr_member.member_status IS '회원 상태';
COMMENT ON COLUMN mbr_member.lock_yn IS '잠금 여부';
COMMENT ON COLUMN mbr_member.withdraw_yn IS '탈퇴 여부';
COMMENT ON COLUMN mbr_member.channel_code IS '가입 채널 코드';
COMMENT ON COLUMN mbr_member.joined_at IS '가입일시';
COMMENT ON COLUMN mbr_member.last_login_at IS '최근 로그인일시';
COMMENT ON COLUMN mbr_member.description IS '회원 설명';
COMMENT ON COLUMN mbr_member.version_no IS '회원 낙관적 잠금 Version';
COMMENT ON COLUMN mbr_member.created_by IS '등록자';
COMMENT ON COLUMN mbr_member.created_at IS '등록일시';
COMMENT ON COLUMN mbr_member.updated_by IS '수정자';
COMMENT ON COLUMN mbr_member.updated_at IS '수정일시';
CREATE OR REPLACE FUNCTION fn_mbr_member_touch() RETURNS trigger AS $$
BEGIN
    NEW.updated_at := CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_mbr_member_touch BEFORE UPDATE ON mbr_member
FOR EACH ROW EXECUTE FUNCTION fn_mbr_member_touch();

CREATE TABLE mbr_member_login_history (
    login_history_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    member_id BIGINT,
    login_domain VARCHAR(30) NOT NULL DEFAULT 'MBR',
    member_no VARCHAR(50),
    customer_no VARCHAR(50),
    login_id VARCHAR(80) NOT NULL,
    login_result VARCHAR(30) NOT NULL,
    login_ip VARCHAR(50),
    user_agent VARCHAR(500),
    failure_reason VARCHAR(500),
    transaction_global_id VARCHAR(34),
    module_id VARCHAR(3),
    was_id VARCHAR(7),
    server_instance_id VARCHAR(200),
    created_by VARCHAR(100) NOT NULL DEFAULT 'SYSTEM',
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by VARCHAR(100) NOT NULL DEFAULT 'SYSTEM',
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (login_history_id),
    CONSTRAINT fk_mbr_member_login_history_member FOREIGN KEY (member_id) REFERENCES mbr_member (id) ON DELETE CASCADE
);
CREATE INDEX ix_mbr_member_login_member_time ON mbr_member_login_history (member_id, created_at);
CREATE INDEX ix_mbr_member_login_global ON mbr_member_login_history (transaction_global_id);
COMMENT ON TABLE mbr_member_login_history IS 'MBR 회원 로그인 이력';
COMMENT ON COLUMN mbr_member_login_history.login_history_id IS '회원 로그인 이력 순번';
COMMENT ON COLUMN mbr_member_login_history.member_id IS '회원 순번';
COMMENT ON COLUMN mbr_member_login_history.login_domain IS '로그인 도메인';
COMMENT ON COLUMN mbr_member_login_history.member_no IS '회원 번호';
COMMENT ON COLUMN mbr_member_login_history.customer_no IS '고객 번호';
COMMENT ON COLUMN mbr_member_login_history.login_id IS '로그인 ID';
COMMENT ON COLUMN mbr_member_login_history.login_result IS '로그인 결과';
COMMENT ON COLUMN mbr_member_login_history.login_ip IS '로그인 IP';
COMMENT ON COLUMN mbr_member_login_history.user_agent IS 'User-Agent';
COMMENT ON COLUMN mbr_member_login_history.failure_reason IS '로그인 실패 사유';
COMMENT ON COLUMN mbr_member_login_history.transaction_global_id IS 'CPF 트랜잭션 글로벌 ID';
COMMENT ON COLUMN mbr_member_login_history.module_id IS '모듈 ID';
COMMENT ON COLUMN mbr_member_login_history.was_id IS 'WAS ID';
COMMENT ON COLUMN mbr_member_login_history.server_instance_id IS '서버 인스턴스 ID';
COMMENT ON COLUMN mbr_member_login_history.created_by IS '등록자';
COMMENT ON COLUMN mbr_member_login_history.created_at IS '등록일시';
COMMENT ON COLUMN mbr_member_login_history.updated_by IS '수정자';
COMMENT ON COLUMN mbr_member_login_history.updated_at IS '수정일시';
CREATE OR REPLACE FUNCTION fn_mbr_member_login_history_touch() RETURNS trigger AS $$
BEGIN
    NEW.updated_at := CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_mbr_member_login_history_touch BEFORE UPDATE ON mbr_member_login_history
FOR EACH ROW EXECUTE FUNCTION fn_mbr_member_login_history_touch();

CREATE TABLE mbr_member_no_issue_history (
    issue_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    member_no VARCHAR(50) NOT NULL,
    issue_type VARCHAR(20) NOT NULL,
    issued_by VARCHAR(100) NOT NULL,
    issued_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (issue_id),
    CONSTRAINT uk_mbr_member_no_issue_history_no UNIQUE (member_no)
);
COMMENT ON TABLE mbr_member_no_issue_history IS 'MBR 회원번호 발급 이력';
COMMENT ON COLUMN mbr_member_no_issue_history.issue_id IS 'Issue identifier';
COMMENT ON COLUMN mbr_member_no_issue_history.member_no IS 'Member number';
COMMENT ON COLUMN mbr_member_no_issue_history.issue_type IS 'Issue type';
COMMENT ON COLUMN mbr_member_no_issue_history.issued_by IS 'Issuer';
COMMENT ON COLUMN mbr_member_no_issue_history.issued_at IS 'Issue time';

CREATE TABLE mbr_member_no_sequence (
    sequence_value BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requested_by VARCHAR(100) NOT NULL,
    requested_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (sequence_value)
);
COMMENT ON TABLE mbr_member_no_sequence IS 'MBR 회원번호 분산 채번';
COMMENT ON COLUMN mbr_member_no_sequence.sequence_value IS 'Sequence value';
COMMENT ON COLUMN mbr_member_no_sequence.requested_by IS 'Requester';
COMMENT ON COLUMN mbr_member_no_sequence.requested_at IS 'Request time';

CREATE TABLE mbr_member_role (
    member_role_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    member_id BIGINT NOT NULL,
    service_code VARCHAR(30) NOT NULL DEFAULT 'MBR',
    role_code VARCHAR(50) NOT NULL,
    role_name VARCHAR(100),
    role_type VARCHAR(30) NOT NULL DEFAULT 'SERVICE',
    grade_code VARCHAR(50),
    temporary_yn CHAR(1) NOT NULL DEFAULT 'N',
    expire_at TIMESTAMP,
    granted_by VARCHAR(100),
    granted_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    revoked_by VARCHAR(100),
    revoked_at TIMESTAMP,
    use_yn CHAR(1) NOT NULL DEFAULT 'Y',
    grant_reason VARCHAR(500),
    version_no BIGINT NOT NULL DEFAULT 0,
    created_by VARCHAR(100) NOT NULL DEFAULT 'SYSTEM',
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by VARCHAR(100) NOT NULL DEFAULT 'SYSTEM',
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (member_role_id),
    CONSTRAINT uk_mbr_member_role UNIQUE (member_id, service_code, role_code),
    CONSTRAINT ck_mbr_member_role_version CHECK (version_no >= 0),
    CONSTRAINT fk_mbr_member_role_member FOREIGN KEY (member_id) REFERENCES mbr_member (id) ON DELETE CASCADE
);
CREATE INDEX ix_mbr_member_role_member ON mbr_member_role (member_id, use_yn);
COMMENT ON TABLE mbr_member_role IS 'MBR 회원 권한';
COMMENT ON COLUMN mbr_member_role.member_role_id IS '회원 권한 순번';
COMMENT ON COLUMN mbr_member_role.member_id IS '회원 순번';
COMMENT ON COLUMN mbr_member_role.service_code IS '서비스 코드';
COMMENT ON COLUMN mbr_member_role.role_code IS '회원 역할 코드';
COMMENT ON COLUMN mbr_member_role.role_name IS '회원 역할명';
COMMENT ON COLUMN mbr_member_role.role_type IS '회원 역할 유형';
COMMENT ON COLUMN mbr_member_role.grade_code IS '회원 등급 코드';
COMMENT ON COLUMN mbr_member_role.temporary_yn IS '임시 권한 여부';
COMMENT ON COLUMN mbr_member_role.expire_at IS '권한 만료일시';
COMMENT ON COLUMN mbr_member_role.granted_by IS '권한 부여자';
COMMENT ON COLUMN mbr_member_role.granted_at IS '권한 부여일시';
COMMENT ON COLUMN mbr_member_role.revoked_by IS '권한 회수자';
COMMENT ON COLUMN mbr_member_role.revoked_at IS '권한 회수일시';
COMMENT ON COLUMN mbr_member_role.use_yn IS '사용 여부';
COMMENT ON COLUMN mbr_member_role.grant_reason IS '권한 부여/갱신 사유';
COMMENT ON COLUMN mbr_member_role.version_no IS '권한 낙관적 잠금 Version';
COMMENT ON COLUMN mbr_member_role.created_by IS '등록자';
COMMENT ON COLUMN mbr_member_role.created_at IS '등록일시';
COMMENT ON COLUMN mbr_member_role.updated_by IS '수정자';
COMMENT ON COLUMN mbr_member_role.updated_at IS '수정일시';
CREATE OR REPLACE FUNCTION fn_mbr_member_role_touch() RETURNS trigger AS $$
BEGIN
    NEW.updated_at := CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_mbr_member_role_touch BEFORE UPDATE ON mbr_member_role
FOR EACH ROW EXECUTE FUNCTION fn_mbr_member_role_touch();

CREATE TABLE mbr_member_role_history (
    history_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    member_id BIGINT NOT NULL,
    service_code VARCHAR(30) NOT NULL,
    role_code VARCHAR(50) NOT NULL,
    action_type VARCHAR(30) NOT NULL,
    reason VARCHAR(500) NOT NULL,
    before_data TEXT,
    after_data TEXT,
    operator_id VARCHAR(100),
    created_by VARCHAR(100) NOT NULL DEFAULT 'SYSTEM',
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by VARCHAR(100) NOT NULL DEFAULT 'SYSTEM',
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (history_id),
    CONSTRAINT fk_mbr_member_role_history_member FOREIGN KEY (member_id) REFERENCES mbr_member (id) ON DELETE CASCADE
);
CREATE INDEX ix_mbr_member_role_history_member ON mbr_member_role_history (member_id, created_at);
COMMENT ON TABLE mbr_member_role_history IS 'MBR 회원 권한 변경 이력';
COMMENT ON COLUMN mbr_member_role_history.history_id IS '회원 권한 이력 순번';
COMMENT ON COLUMN mbr_member_role_history.member_id IS '회원 순번';
COMMENT ON COLUMN mbr_member_role_history.service_code IS '서비스 코드';
COMMENT ON COLUMN mbr_member_role_history.role_code IS '회원 역할 코드';
COMMENT ON COLUMN mbr_member_role_history.action_type IS '권한 행위 유형';
COMMENT ON COLUMN mbr_member_role_history.reason IS '권한 변경 사유';
COMMENT ON COLUMN mbr_member_role_history.before_data IS '변경 전 데이터';
COMMENT ON COLUMN mbr_member_role_history.after_data IS '변경 후 데이터';
COMMENT ON COLUMN mbr_member_role_history.operator_id IS '처리 운영자 ID';
COMMENT ON COLUMN mbr_member_role_history.created_by IS '등록자';
COMMENT ON COLUMN mbr_member_role_history.created_at IS '등록일시';
COMMENT ON COLUMN mbr_member_role_history.updated_by IS '수정자';
COMMENT ON COLUMN mbr_member_role_history.updated_at IS '수정일시';
CREATE OR REPLACE FUNCTION fn_mbr_member_role_history_touch() RETURNS trigger AS $$
BEGIN
    NEW.updated_at := CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_mbr_member_role_history_touch BEFORE UPDATE ON mbr_member_role_history
FOR EACH ROW EXECUTE FUNCTION fn_mbr_member_role_history_touch();

CREATE TABLE mbr_member_role_operation (
    idempotency_key VARCHAR(120) NOT NULL,
    member_id BIGINT NOT NULL,
    service_code VARCHAR(30) NOT NULL,
    role_code VARCHAR(50) NOT NULL,
    operation_type VARCHAR(20) NOT NULL,
    operation_status VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    result_version BIGINT,
    result_use_yn CHAR(1),
    created_by VARCHAR(100) NOT NULL,
    created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    completed_at TIMESTAMP(3),
    PRIMARY KEY (idempotency_key),
    CONSTRAINT fk_mbr_member_role_operation_member FOREIGN KEY (member_id) REFERENCES mbr_member (id) ON DELETE CASCADE
);
CREATE INDEX ix_mbr_member_role_operation_member ON mbr_member_role_operation (member_id, created_at);
COMMENT ON TABLE mbr_member_role_operation IS 'MBR 회원 권한 멱등 변경 이력';
COMMENT ON COLUMN mbr_member_role_operation.idempotency_key IS 'Idempotency key';
COMMENT ON COLUMN mbr_member_role_operation.member_id IS 'Member identifier';
COMMENT ON COLUMN mbr_member_role_operation.service_code IS 'Service code';
COMMENT ON COLUMN mbr_member_role_operation.role_code IS 'Role code';
COMMENT ON COLUMN mbr_member_role_operation.operation_type IS 'Operation type';
COMMENT ON COLUMN mbr_member_role_operation.operation_status IS 'Operation status';
COMMENT ON COLUMN mbr_member_role_operation.result_version IS 'Result version';
COMMENT ON COLUMN mbr_member_role_operation.result_use_yn IS 'Result usage flag';
COMMENT ON COLUMN mbr_member_role_operation.created_by IS 'Creator';
COMMENT ON COLUMN mbr_member_role_operation.created_at IS 'Creation time';
COMMENT ON COLUMN mbr_member_role_operation.completed_at IS 'Completion time';

CREATE TABLE mbr_sample_item (
    sample_item_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    sample_key VARCHAR(100) NOT NULL,
    item_name VARCHAR(200) NOT NULL,
    status_code VARCHAR(30) NOT NULL DEFAULT 'ACTIVE',
    version_no BIGINT NOT NULL DEFAULT 0,
    idempotency_key VARCHAR(100) NOT NULL,
    transaction_id CHAR(34) NOT NULL,
    transaction_sequence BIGINT NOT NULL DEFAULT 1,
    transaction_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_yn CHAR(1) NOT NULL DEFAULT 'N',
    created_by VARCHAR(100) NOT NULL DEFAULT 'MBR',
    created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by VARCHAR(100) NOT NULL DEFAULT 'MBR',
    updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (sample_item_id),
    CONSTRAINT uk_mbr_sample_item_key UNIQUE (sample_key),
    CONSTRAINT uk_mbr_sample_item_idempotency UNIQUE (idempotency_key),
    CONSTRAINT ck_mbr_sample_item_status CHECK (status_code IN ('ACTIVE','INACTIVE')),
    CONSTRAINT ck_mbr_sample_item_version CHECK (version_no >= 0),
    CONSTRAINT ck_mbr_sample_item_sequence CHECK (transaction_sequence >= 1),
    CONSTRAINT ck_mbr_sample_item_deleted CHECK (deleted_yn IN ('Y','N'))
);
CREATE INDEX ix_mbr_sample_item_status ON mbr_sample_item (status_code, deleted_yn, sample_item_id);
CREATE INDEX ix_mbr_sample_item_transaction ON mbr_sample_item (transaction_id, transaction_sequence);
COMMENT ON TABLE mbr_sample_item IS 'CPF Generated Domain Minimal CRUD Sample';
COMMENT ON COLUMN mbr_sample_item.sample_item_id IS '샘플 항목 ID';
COMMENT ON COLUMN mbr_sample_item.sample_key IS '업무 중복 식별 키';
COMMENT ON COLUMN mbr_sample_item.item_name IS '최소 업무 데이터명';
COMMENT ON COLUMN mbr_sample_item.status_code IS '상태 코드';
COMMENT ON COLUMN mbr_sample_item.version_no IS '낙관적 잠금 버전';
COMMENT ON COLUMN mbr_sample_item.idempotency_key IS '명령 멱등 키';
COMMENT ON COLUMN mbr_sample_item.transaction_id IS 'CPF transactionId';
COMMENT ON COLUMN mbr_sample_item.transaction_sequence IS '동일 거래 내 변경 순번';
COMMENT ON COLUMN mbr_sample_item.transaction_at IS '마지막 거래 시각';
COMMENT ON COLUMN mbr_sample_item.deleted_yn IS '논리 삭제 여부';
COMMENT ON COLUMN mbr_sample_item.created_by IS '등록자';
COMMENT ON COLUMN mbr_sample_item.created_at IS '등록일시';
COMMENT ON COLUMN mbr_sample_item.updated_by IS '수정자';
COMMENT ON COLUMN mbr_sample_item.updated_at IS '수정일시';
CREATE OR REPLACE FUNCTION fn_mbr_sample_item_touch() RETURNS trigger AS $$
BEGIN
    NEW.updated_at := CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_mbr_sample_item_touch BEFORE UPDATE ON mbr_sample_item
FOR EACH ROW EXECUTE FUNCTION fn_mbr_sample_item_touch();
